import pandas as pd

def group_employees(employees: pd.DataFrame) -> pd.DataFrame:
    salary_counts = employees["salary"].value_counts()
    shared_salaries = salary_counts[salary_counts >= 2].index
    df = employees[employees["salary"].isin(shared_salaries)].copy()
    if df.empty:
        return pd.DataFrame(columns=["employee_id", "name", "salary", "team_id"])
    unique_salaries = sorted(df["salary"].unique())
    salary_to_team = {sal: i + 1 for i, sal in enumerate(unique_salaries)}
    df["team_id"] = df["salary"].map(salary_to_team)
    return df.sort_values(by=["team_id", "employee_id"])[["employee_id", "name", "salary", "team_id"]]
